import { STORAGE_KEYS } from "./core/storageKeys.js";
import { safeGetJSON, safeSetJSON } from "./safeStorage.js";

const norm = (s) => String(s || '').toLowerCase().replace(/đ/g, 'd').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
export const TOC_PDF_OFFSET = 1;
export const FILE_TOC_PREFIX = STORAGE_KEYS.TOC_FILE_MARKER;
export function makeFileTocKey(book) {
  const fn = String(book?.filename || "").trim().toLowerCase();
  if (!fn) return "";
  return `${FILE_TOC_PREFIX}${fn}`;
}
export function findTocBook(book) {
  // Per-file isolation: nếu có filename, ưu tiên cache per-file và file-specific custom, không dùng chung
  if (book?.filename) {
    // 1. Cache per-file (toc_${filename}) — nơi BookReader lưu chỉnh sửa per-file mới nhất (cache, rebuildable)
    try {
      const cacheKey = `${STORAGE_KEYS.TOC_FILE_PREFIX}${book.filename}`;
      const parsed = safeGetJSON(cacheKey, null, v => v && Array.isArray(v.items));
      if (parsed && Array.isArray(parsed.items) && parsed.items.length) {
        return {
          key: makeFileTocKey(book),
          title: book.title || book.filename || "muc-luc",
          grade: book.grade,
          subject: book.subject,
          term: book.term,
          items: parsed.items,
          _fromCache: true,
        };
      }
    } catch {}
    // 2. File-specific custom trong sgk_toc_custom_v1
    const allCustom = getCustomTocBooks();
    const fileKey = makeFileTocKey(book);
    if (fileKey) {
      const hitFile = allCustom.find((b) => b.key === fileKey);
      if (hitFile) return hitFile;
      // cũng check merged (đề phòng)
      const allMerged = getMergedTocBooks();
      const hitMergedFile = allMerged.find((b) => b.key === fileKey);
      if (hitMergedFile) return hitMergedFile;
    }
    // 3. Static gốc (không dùng custom generic để tránh dùng chung)
    const subj = String(book.subject || "").trim();
    const grade = book.grade;
    const term = book.term;
    const keysToTry = [
      norm(`${subj}${grade}t${term}`),
      norm(`${subj}${grade}`),
      norm(`${subj}t${term}`),
      norm(subj),
    ].filter(Boolean);
    for (const k of keysToTry) {
      const hitStatic = tocBooks.find((b) => b.key === k);
      if (hitStatic) return hitStatic;
    }
    return null;
  }
  // Không có filename: tra generic (dùng cho DataToolsView, global)
  const all = getMergedTocBooks();
  const subj = String(book.subject || "").trim();
  const grade = book.grade;
  const term = book.term;
  const keysToTry = [
    norm(`${subj}${grade}t${term}`),
    norm(`${subj}${grade}`),
    norm(`${subj}t${term}`),
    norm(subj),
  ].filter(Boolean);
  for (const k of keysToTry) {
    const hit = all.find((b) => b.key === k);
    if (hit) return hit;
  }
  return null;
}
// Trang sách in (hiển thị) <-> PDF page (1-based) — dùng chung cho toolbar và mục lục.
export const bookToPdf = (n) => Math.max(1, (Number(n) || 1) + TOC_PDF_OFFSET);
export const pdfToBook = (p) => Math.max(1, (Number(p) || 1) - TOC_PDF_OFFSET);

// ── Custom TOC via Excel — giữ mục lục gốc, thêm/ghi đè qua localStorage ──
export const CUSTOM_TOC_KEY = STORAGE_KEYS.TOC_CUSTOM;
export function getCustomTocBooks() {
  try {
    const arr = safeGetJSON(CUSTOM_TOC_KEY, [], Array.isArray);
    return Array.isArray(arr) ? arr : [];
  } catch { return []; }
}
export function getMergedTocBooks() {
  const custom = getCustomTocBooks();
  if (!custom.length) return tocBooks;
  const map = new Map(tocBooks.map(b => [b.key, b]));
  for (const b of custom) map.set(b.key, b);
  return [...map.values()];
}
export function saveCustomTocBooks(books) {
  const r = safeSetJSON(CUSTOM_TOC_KEY, books);
  if (!r.ok) console.warn("[tocData] saveCustom failed", r.error);
  return r.ok;
}
export function upsertTocBook(book) {
  if (!book || !book.key) return false;
  const cur = getCustomTocBooks();
  const idx = cur.findIndex(b => b.key === book.key);
  if (idx >= 0) cur[idx] = book; else cur.push(book);
  return saveCustomTocBooks(cur);
}
export function deleteCustomTocBook(key) {
  const cur = getCustomTocBooks().filter(b => b.key !== key);
  return saveCustomTocBooks(cur);
}
export function makeTocKey({ subject, grade, term }) {
  return norm(`${subject}${grade}t${term}`);
}
